// or nil if none found.
func (m *BalanceResults) ValidateAll() error {
	return m.validate(true)
}

func (m *BalanceResults) validate(all bool) error {
	if m == nil {
		return nil
	}

	var errors []error

	if m.GetTotal() == nil {
		err := BalanceResultsValidationError{
			field:  "Total",
			reason: "value is required",
		}
		if !all {
			return err
		}
		errors = append(errors, err)
	}

	if all {
		switch v := interface{}(m.GetTotal()).(type) {
		case interface{ ValidateAll() error }:
			if err := v.ValidateAll(); err != nil {
				errors = append(errors, BalanceResultsValidationError{
					field:  "Total",
					reason: "embedded message failed validation",
					cause:  err,
				})
			}
		case interface{ Validate() error }:
			if err := v.Validate(); err != nil {
				errors = append(errors, BalanceResultsValidationError{
					field:  "Total",
					reason: "embedded message failed validation",
					cause:  err,
				})
			}
		}
	} else if v, ok := interface{}(m.GetTotal()).(interface{ Validate() error }); ok {
		if err := v.Validate(); err != nil {
			return BalanceResultsValidationError{
				field:  "Total",
				reason: "embedded message failed validation",
				cause:  err,
			}
		}
	}

	if l := len(m.GetOptionBalances()); l < 2 || l > 10 {
		err := BalanceResultsValidationError{
			field:  "OptionBalances",
			reason: "value must contain between 2 and 10 items, inclusive",
		}
		if !all {
			return err
		}
		errors = append(errors, err)
	}

	for idx, item := range m.GetOptionBalances() {
		_, _ = idx, item

		if all {
			switch v := interface{}(item).(type) {
			case interface{ ValidateAll() error }:
				if err := v.ValidateAll(); err != nil {
					errors = append(errors, BalanceResultsValidationError{
						field:  fmt.Sprintf("OptionBalances[%v]", idx),
						reason: "embedded message failed validation",
						cause:  err,
					})
				}
			case interface{ Validate() error }:
				if err := v.Validate(); err != nil {
					errors = append(errors, BalanceResultsValidationError{
						field:  fmt.Sprintf("OptionBalances[%v]", idx),
						reason: "embedded message failed validation",
						cause:  err,
					})
				}
			}
		} else if v, ok := interface{}(item).(interface{ Validate() error }); ok {
			if err := v.Validate(); err != nil {
				return BalanceResultsValidationError{
					field:  fmt.Sprintf("OptionBalances[%v]", idx),
					reason: "embedded message failed validation",
					cause:  err,
				}
			}
		}

	}

	if len(errors) > 0 {
		return BalanceResultsMultiError(errors)
	}

	return nil
}

